package dusrelpdf_test

import (
	"bytes"
	"image"
	"image/color"
	"image/jpeg"
	"image/png"
	"os"
	"path/filepath"
	"testing"

	dusrelpdf "github.com/dusmamud/dusrelpdf-go"
)

// Fixtures are real PDFs generated by the repo's own CLI:
//   cargo run -p dusrelpdf-cli -- mock --pages 3 -o testdata/three.pdf
//   cargo run -p dusrelpdf-cli -- mock --pages 5 -o testdata/five.pdf
// Every test goes through the real cdylib (cgo) and the real Rust core.

func fixture(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	return b
}

func pageCount(t *testing.T, pdf []byte) uint32 {
	t.Helper()
	info, err := dusrelpdf.GetPDFInfo(pdf, nil)
	if err != nil {
		t.Fatalf("GetPDFInfo: %v", err)
	}
	return info.PageCount
}

// makePNG builds a small opaque PNG in memory (stdlib only) so the
// image tests do not depend on a committed binary fixture.
func makePNG(t *testing.T, w, h int) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for x := 0; x < w; x++ {
		for y := 0; y < h; y++ {
			img.Set(x, y, color.RGBA{uint8(x * 255 / w), 60, uint8(y * 255 / h), 255})
		}
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		t.Fatalf("png.Encode: %v", err)
	}
	return buf.Bytes()
}

func makeJPEG(t *testing.T, w, h int) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for x := 0; x < w; x++ {
		for y := 0; y < h; y++ {
			img.Set(x, y, color.RGBA{uint8(x * 255 / w), 60, uint8(y * 255 / h), 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		t.Fatalf("jpeg.Encode: %v", err)
	}
	return buf.Bytes()
}

func TestVersion(t *testing.T) {
	if v := dusrelpdf.Version(); v != "0.1.0" {
		t.Fatalf("Version() = %q, want 0.1.0", v)
	}
}

func TestMerge(t *testing.T) {
	a := fixture(t, "three.pdf")
	b := fixture(t, "five.pdf")
	out, err := dusrelpdf.Merge([][]byte{a, b}, nil)
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	if got := pageCount(t, out); got != 8 {
		t.Fatalf("merged page count = %d, want 8", got)
	}
	if !bytes.HasPrefix(out, []byte("%PDF-")) {
		t.Fatalf("merged output does not start with %%PDF-")
	}

	// Partial options: disabling bookmarks must still merge fine.
	out, err = dusrelpdf.Merge([][]byte{a}, &dusrelpdf.MergeOptions{AddBookmarks: dusrelpdf.Bool(false)})
	if err != nil {
		t.Fatalf("Merge with options: %v", err)
	}
	if got := pageCount(t, out); got != 3 {
		t.Fatalf("merged page count = %d, want 3", got)
	}
}

func TestMergeEmptyInput(t *testing.T) {
	_, err := dusrelpdf.Merge(nil, nil)
	if err == nil {
		t.Fatal("Merge(nil) should fail")
	}
	derr, ok := err.(*dusrelpdf.Error)
	if !ok {
		t.Fatalf("error type = %T, want *dusrelpdf.Error", err)
	}
	if derr.Code != "EMPTY_INPUT" {
		t.Fatalf("code = %q, want EMPTY_INPUT", derr.Code)
	}
	if derr.MessageHI == "" {
		t.Fatal("Hindi message is empty")
	}
}

func TestSplit(t *testing.T) {
	pdf := fixture(t, "five.pdf")
	outs, err := dusrelpdf.Split(pdf, [][]uint32{{1, 2}, {3, 4, 5}}, nil)
	if err != nil {
		t.Fatalf("Split: %v", err)
	}
	if len(outs) != 2 {
		t.Fatalf("len(outs) = %d, want 2", len(outs))
	}
	if got := pageCount(t, outs[0]); got != 2 {
		t.Fatalf("outs[0] pages = %d, want 2", got)
	}
	if got := pageCount(t, outs[1]); got != 3 {
		t.Fatalf("outs[1] pages = %d, want 3", got)
	}
}

func TestSplitRanges(t *testing.T) {
	pdf := fixture(t, "five.pdf")
	outs, err := dusrelpdf.SplitRanges(pdf, "1-2,3-5", nil)
	if err != nil {
		t.Fatalf("SplitRanges: %v", err)
	}
	if len(outs) != 2 || pageCount(t, outs[0]) != 2 || pageCount(t, outs[1]) != 3 {
		t.Fatalf("unexpected split: %d outputs", len(outs))
	}
}

func TestSplitEachPage(t *testing.T) {
	pdf := fixture(t, "three.pdf")
	outs, err := dusrelpdf.SplitEachPage(pdf, nil)
	if err != nil {
		t.Fatalf("SplitEachPage: %v", err)
	}
	if len(outs) != 3 {
		t.Fatalf("len(outs) = %d, want 3", len(outs))
	}
	for i, out := range outs {
		if got := pageCount(t, out); got != 1 {
			t.Fatalf("outs[%d] pages = %d, want 1", i, got)
		}
	}
}

