func TestPlaceSignature(t *testing.T) {
	pdf := fixture(t, "three.pdf")
	png := makePNG(t, 200, 80)
	out, err := dusrelpdf.PlaceSignature(pdf, png, nil)
	if err != nil {
		t.Fatalf("PlaceSignature: %v", err)
	}
	if got := pageCount(t, out); got != 3 {
		t.Fatalf("pages = %d, want 3", got)
	}

	// Empty image is an error.
	_, err = dusrelpdf.PlaceSignature(pdf, nil, nil)
	if err == nil {
		t.Fatal("PlaceSignature(nil image) should fail")
	}
}

func TestBulkExtract(t *testing.T) {
	pdf := fixture(t, "three.pdf")
	items, err := dusrelpdf.BulkExtract(pdf, [][]uint32{{1}, {2, 3}, {9}}, nil)
	if err != nil {
		t.Fatalf("BulkExtract: %v", err)
	}
	if len(items) != 3 {
		t.Fatalf("len(items) = %d, want 3", len(items))
	}
	if len(items[0].PDF) == 0 || pageCount(t, items[0].PDF) != 1 {
		t.Fatal("items[0] should be a 1-page PDF")
	}
	if len(items[1].PDF) == 0 || pageCount(t, items[1].PDF) != 2 {
		t.Fatal("items[1] should be a 2-page PDF")
	}
	if items[2].PDF != nil {
		t.Fatal("items[2].PDF should be nil (page 9 is out of range)")
	}
	if items[2].ErrorCode != "PAGE_OUT_OF_RANGE" {
		t.Fatalf("items[2].ErrorCode = %q, want PAGE_OUT_OF_RANGE", items[2].ErrorCode)
	}
	// One bad selection must not fail the whole batch (error is nil).
}
